  "piercing.tragus.badAngleConsequence": "มุมที่เอียงเข้าด้านในบังคับให้จานรองดันเข้ากับผนังช่องหู ทำให้ระคายเคืองเฉียบพลัน ช่องหูอุดตัน และความชื้นสะสมเรื้อรัง",
  "piercing.tragus.positioning": "<p><strong>จุดสังเกตทางกายวิภาค:</strong> กึ่งกลางของส่วนนูนของ tragus ระหว่างฐานด้านหน้าและขอบด้านนอก</p>",
