  "piercing.nostril.positioning": "<p><strong>จุดสังเกตทางกายวิภาค:</strong> รอยพับธรรมชาติหรือร่อง supra-alar ของส่วนบานจมูก</p>",
  "piercing.nostril.refuse": "<p><strong>เกณฑ์การปฏิเสธ:</strong> การติดเชื้อทางจมูกที่ยังดำเนินอยู่ หรือภาวะจมูกอักเสบจากภูมิแพ้รุนแรงที่กำเริบ</p>",
  "piercing.nostril.aftercare": "<p>ห้ามหมุนหรือสัมผัสเครื่องประดับ พ่นน้ำเกลือทั้งด้านในและด้านนอก</p>",
  "piercing.septum.category": "การเจาะใบหน้าและช่องปาก",
