  "piercing.septum.jewelryType": "บาร์เบลล์วงกลม (เกือกม้า) [มาตรฐานเริ่มต้น]",
  "piercing.septum.downsizeTime": "6-8 สัปดาห์",
  "piercing.septum.whyThisAngle": "การเจาะสูงและไปข้างหน้าผ่าน \"จุดหวาน\" ของเยื่อช่วยตัดเสียงกรอบแกรบของกระดูกอ่อน ทำให้เครื่องประดับวงกลมห้อยตรงและอยู่กึ่งกลาง ไม่เอียงไปข้างหน้าหรือข้างหลัง",
  "piercing.septum.badAngleConsequence": "การผ่านกระดูกอ่อนแข็งแทนจุดนิ่มที่อยู่ข้างหน้า จะเจ็บมากกว่า หายช้ากว่า (6-12 เดือน) ปวดนานและทำให้เครื่องประดับห้อยเอียง",
  "piercing.septum.positioning": "<p><strong>จุดสังเกตทางกายวิภาค:</strong> สูงที่ยอดปลายจมูก ภายในเยื่อบางระหว่างกระดูกอ่อนส่วนล่างและส่วนบน</p>",
  "piercing.septum.refuse": "<p><strong>เกณฑ์การปฏิเสธ:</strong> เยื่อกั้นจมูกที่คดบังจุดหวาน หรือไม่มีช่องเยื่อ</p>",
  "piercing.septum.aftercare": "<p>แช่ด้วยถ้วยน้ำเกลือ พับขึ้นเฉพาะเมื่อจำเป็นในระยะการหาย</p>",
  "piercing.bridge.category": "การเจาะใบหน้าและช่องปาก",
