  "piercing.bridge.whyThisAngle": "การจัดแนวราบขนานกับเส้นตาทำให้รูปลักษณ์สมมาตรข้ามแนวกึ่งกลางใบหน้า และแรงตึงสม่ำเสมอบนหนังแท้ของสันจมูก",
  "piercing.bridge.badAngleConsequence": "ช่องสะพานจมูกที่เอียงหรือไม่สม่ำเสมอทำให้เคลื่อนที่ทางเดียวอย่างรวดเร็ว ผิวบางลง และเกิดแผลเป็นจากการปฏิเสธที่น่าเกลียดระหว่างดวงตา",
  "piercing.bridge.positioning": "<p><strong>จุดสังเกตทางกายวิภาค:</strong> จุดสูงสุดของสันจมูกระหว่างหัวตาทั้งสองข้าง</p>",
  "piercing.bridge.refuse": "<p><strong>เกณฑ์การปฏิเสธ:</strong> ผิวตึงเหนือกระดูกจมูกโดยมีความลึกของเนื้อเยื่อที่หยิกได้ไม่เพียงพอ</p>",
  "piercing.bridge.aftercare": "<p>หลีกเลี่ยงการให้กรอบแว่นตาหรือแว่นกันแดดสัมผัสเครื่องประดับที่กำลังหาย</p>",
