  "piercing.eyebrow.whyThisAngle": "การเจาะตั้งฉากกับสันคิ้วทำให้ช่องทางมีความลึกสม่ำเสมอตลอด ซึ่งช่วยลดโอกาสที่จะดันออกมา",
  "piercing.eyebrow.badAngleConsequence": "จุดเข้าที่ตื้นหรือเอียงทำให้ช่องทางรับแรงตึงจากการเคลื่อนไหวของสีหน้าตลอดเวลา นำไปสู่การเคลื่อนที่และการดันออกอย่างช้า ๆ",
  "piercing.eyebrow.positioning": "<p><strong>จุดสังเกตทางกายวิภาค:</strong> หนึ่งในสามส่วนนอกของสัน supraorbital ด้านข้างของรอยบาก supraorbital nerve</p>",
  "piercing.eyebrow.refuse": "<p><strong>เกณฑ์การปฏิเสธ:</strong> กระดูกคิ้วแบนที่ไม่มีรอยพับผิวที่ยืดหยุ่น</p>",
  "piercing.eyebrow.aftercare": "<p>ทำความสะอาดด้วยน้ำเกลือ หลีกเลี่ยงเครื่องสำอางหรือเจลคิ้วบนตำแหน่งที่เจาะ</p>",
  "piercing.labret.category": "การเจาะใบหน้าและช่องปาก",
