  "piercing.labret.whyThisAngle": "มุมตั้งฉากเคร่งครัดทำให้จานภายในกว้างและแบนวางขนานกับเหงือก ฝังอย่างนุ่มนวลในโพรงเยื่อบุโดยไม่กัดกร่อนเคลือบฟันหรือเหงือก",
  "piercing.labret.badAngleConsequence": "มุมเอียงลงบังคับให้ขอบของจานไทเทเนียมแข็งกดตรงกับฟันตัดล่างและเหงือก ทำให้เหงือกร่นถาวรและเคลือบฟันแตก",
  "piercing.labret.positioning": "<p><strong>จุดสังเกตทางกายวิภาค:</strong> อยู่กึ่งกลางของเส้นกึ่งกลางริมฝีปากล่าง ใต้ขอบ vermilion</p>",
  "piercing.labret.refuse": "<p><strong>เกณฑ์การปฏิเสธ:</strong> เหงือกร่นรุนแรงที่มีอยู่เดิม หรือรอยโรคเริมในช่องปากที่ยังดำเนินอยู่</p>",
  "piercing.labret.aftercare": "<p>น้ำยาบ้วนปากต้านแบคทีเรียที่ไม่มีแอลกอฮอล์หลังอาหาร และพ่นน้ำเกลือที่ทางเข้าด้านนอก</p>",
