  "piercing.vertical_labret.badAngleConsequence": "ช่องริมฝีปากตื้นทำให้ลูกปัดด้านบนดึงไปข้างหน้า นำไปสู่การเคลื่อนผ่านขอบ vermilion และแผลเป็นที่ริมฝีปากแยก",
  "piercing.vertical_labret.positioning": "<p><strong>จุดสังเกตทางกายวิภาค:</strong> ศูนย์กลางแนวดิ่งจริงของสัน vermilion ริมฝีปากล่าง</p>",
  "piercing.vertical_labret.refuse": "<p><strong>เกณฑ์การปฏิเสธ:</strong> กายวิภาคริมฝีปากบางที่ยื่นของ vermilion ไม่เพียงพอ</p>",
  "piercing.vertical_labret.aftercare": "<p>หลีกเลี่ยงลิปบาล์มหรือลิปสติก ใช้สเปรย์น้ำเกลือปราศจากเชื้อ</p>",
