  "piercing.medusa.badAngleConsequence": "การเอียงด้านข้างหรือแนวดิ่งทำให้ใบหน้าดูไม่สมมาตร และทำให้จานภายขูดเยื่อยึดริมฝีปากบนหรือฟันหน้า",
  "piercing.medusa.positioning": "<p><strong>จุดสังเกตทางกายวิภาค:</strong> ศูนย์กลางแนวดิ่งจริงของร่อง philtrum อยู่เหนือ Cupid’s bow โดยตรง</p>",
  "piercing.medusa.refuse": "<p><strong>เกณฑ์การปฏิเสธ:</strong> philtrum ไม่สมมาตร หรือเยื่อยึดริมฝีปากโตผิดปกติที่ขัดขวางจานภายใน</p>",
  "piercing.medusa.aftercare": "<p>ขั้นตอนการบ้วนปากร่วมกับการพ่นน้ำเกลือด้านนอก</p>",
