  "piercing.tongue.badAngleConsequence": "การเอียงไปข้างหน้าทำให้ลูกปัดด้านบนที่หนักอยู่ระหว่างฟันหน้าโดยตรง เพิ่มความเสี่ยงฟันแตกและเคลือบฟันบิ่นอย่างมาก",
  "piercing.tongue.positioning": "<p><strong>จุดสังเกตทางกายวิภาค:</strong> ร่อง median sulcus กึ่งกลาง ห่างจากปลายลิ้นไปด้านหลัง 15-20 มม. ส่องดูเส้นเลือดดำใต้ลิ้นด้านท้อง</p>",
  "piercing.tongue.refuse": "<p><strong>เกณฑ์การปฏิเสธ:</strong> Ankyloglossia (ลิ้นติดรุนแรง) หรือหลอดเลือดใต้ลิ้นขนาดใหญ่และโดดเด่นอยู่บนแนวกึ่งกลางโดยตรง</p>",
  "piercing.tongue.aftercare": "<p>แช่น้ำแข็งเพื่อลดอาการบวมเริ่มต้น และบ้วนปากด้วยน้ำยาที่ไม่มีแอลกอฮอล์หลังอาหารทุกมื้อ</p>",
