  "piercing.philtrum.whyThisAngle": "ความตั้งฉากเคร่งครัดกับแนวกึ่งกลาง sagittal ทำให้ส่วนหน้าที่ตกแต่งอยู่กึ่งกลางของ Cupid’s bow ขณะที่จานภายในวางแนบเหนือฟันตัดกลาง",
  "piercing.philtrum.badAngleConsequence": "การเอียงด้านข้างหรือแนวดิ่งทำให้ใบหน้าดูไม่สมมาตร และทำให้จานภายในขูดเยื่อยึดริมฝีปากบนหรือฟันหน้า",
  "piercing.philtrum.positioning": "<p><strong>จุดสังเกตทางกายวิภาค:</strong> ศูนย์กลางแนวดิ่งจริงของร่อง philtrum อยู่เหนือ Cupid’s bow โดยตรง</p>",
  "piercing.philtrum.refuse": "<p><strong>เกณฑ์การปฏิเสธ:</strong> philtrum ไม่สมมาตร หรือเยื่อยึดริมฝีปากโตผิดปกติที่ขัดขวางจานภายใน</p>",
  "piercing.philtrum.aftercare": "<p>ขั้นตอนการบ้วนปากร่วมกับการพ่นน้ำเกลือด้านนอก</p>",
