  "piercing.forehead.downsizeTime": "เท้าแองเคอร์คงที่",
  "piercing.forehead.whyThisAngle": "การสอดฐานเท้าที่มีรูพรุนให้แบนราบสนิทภายในช่องใต้ผิวหนัง ทำให้เส้นใยเนื้อเยื่อและคอลลาเจนเติบโตผ่านรูพรุนและล็อกก้านยกแนวดิ่งที่ 90° ให้แนบกับผิว",
  "piercing.forehead.badAngleConsequence": "เท้าแองเคอร์ที่เอียงทำให้ปลายข้างหนึ่งของแผ่นยกขึ้น ส่งผลให้เกิดการเกี่ยวเรื้อรัง เยื่อบุผิวเติบโตลงไป และแองเคอร์ถูกดันออกทั้งหมด",
  "piercing.forehead.positioning": "<p><strong>จุดสังเกตทางกายวิภาค:</strong> ระนาบกระดูกแบนราบ (กระดูกโหนกแก้ม กระดูกอก กระดูกไหปลาร้า โคนข้อมือ)</p>",
  "piercing.forehead.refuse": "<p><strong>เกณฑ์การปฏิเสธ:</strong> บริเวณที่มีแนวโน้มได้รับแรงกระแทกรุนแรงหรือการเสียดสีต่อเนื่องจากสายกระเป๋าและเสื้อผ้า</p>",
  "piercing.forehead.aftercare": "<p>ปิดด้วยผ้าพันแผลปราศจากเชื้อที่ระบายอากาศได้ตลอด 72 ชั่วโมงแรก พ่นน้ำเกลือ</p>",
