  "piercing.upper_lobe.optimalAngle": "90° (ตั้งฉากกับติ่งหูทั้งจากด้านหน้าและด้านข้าง)",
  "piercing.upper_lobe.angleTolerance": "±2°",
  "piercing.upper_lobe.insertionDepth": "4-8 มม. ผ่านเนื้อเยื่อไขมันอ่อนของติ่งหู",
