  "piercing.upper_lobe.downsizeTime": "4-6 สัปดาห์ (พอดีเรียบหลังอาการบวมยุบ)",
  "piercing.upper_lobe.whyThisAngle": "ตั้งฉากกับติ่งหู ด้านหน้าและด้านหลังของเครื่องประดับจะแนบราบกับผิว หากช่องทางเฉียง ขอบด้านหนึ่งจะกดอยู่ และตามเวลารูอาจเลื่อนหรือยืดเป็นร่อง",
  "piercing.upper_lobe.badAngleConsequence": "มุมที่เอียงลงหรือนอกแกนทำให้ด้านหน้าของเครื่องประดับเอียงไปข้างหน้า ขอบจานด้านหลังจะกดลงด้านหลังของติ่งหู ทำให้ระคายเคืองและเครื่องประดับห้อยเอียง",
  "piercing.upper_lobe.positioning": "<p><strong>จุดสังเกตทางกายวิภาค:</strong> กึ่งกลางของติ่งหูส่วนล่างที่นุ่ม สมดุลกับใบหน้าและรอยพับที่มีอยู่ หากเจาะหลายตำแหน่งที่ติ่งหู ควรเว้นระยะให้เครื่องประดับไม่กดทับกัน</p>",
  "piercing.upper_lobe.refuse": "<p><strong>เกณฑ์การปฏิเสธ:</strong> ปฏิเสธหรือเลื่อนออกไปหากมีถุงน้ำใต้ผิวหนังที่ยังใช้งานอยู่ แผลเป็นคีลอยด์รุนแรง ผิวหนังอักเสบที่ยังดำเนินอยู่ หรือปริมาตรเนื้อเยื่อติ่งหูไม่เพียงพอ</p>",
  "piercing.upper_lobe.aftercare": "<p>สเปรย์น้ำเกลือปราศจากเชื้อ 0.9% วันละสองครั้ง หลีกเลี่ยงการนอนทับตำแหน่งที่เจาะ อย่าบิดหรือหมุนเครื่องประดับ</p>",
