  "feedback.your_feedback_has_been_se": "ส่งความคิดเห็นของคุณแล้ว เราจะอ่านอย่างละเอียดและติดต่อกลับโดยเร็ว!",
  "common.oops": "😔 ขออภัย!",
  "feedback.something_went_wrong_plea": "เกิดข้อผิดพลาด โปรดลองอีกครั้ง หรืออีเมลถึงเราโดยตรงที่ patrick@poli-international.com",
  "visualizer.get_notified_of_new_tools": "🔔 รับการแจ้งเตือนเมื่อมีเครื่องมือใหม่!",
  "visualizer.be_first_to_know_when_we": "เป็นคนแรกที่ได้รู้เมื่อเราเปิดตัวเครื่องมือฟรีใหม่สำหรับช่างเจาะมืออาชีพ",
  "visualizer.thanks_we_ll_notify_you_w": "✅ ขอบคุณ! เราจะแจ้งเตือนคุณเมื่อมีการเปิดตัวเครื่องมือใหม่!",
  "visualizer.please_enter_a_valid_emai": "❌ โปรดป้อนที่อยู่อีเมลที่ถูกต้อง",
